// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetDriverConfig What the app needs to work offline
	// (GET /driver/config)
	GetDriverConfig(ctx context.Context, request GetDriverConfigRequestObject) (GetDriverConfigResponseObject, error)
	// DriverSignIn Sign in with a phone number and PIN
	// (POST /driver/login)
	DriverSignIn(ctx context.Context, request DriverSignInRequestObject) (DriverSignInResponseObject, error)
	// DriverSignOut Sign out this device
	// (POST /driver/logout)
	DriverSignOut(ctx context.Context, request DriverSignOutRequestObject) (DriverSignOutResponseObject, error)
	// ChangeDriverPIN Change the PIN
	// (POST /driver/pin)
	ChangeDriverPIN(ctx context.Context, request ChangeDriverPINRequestObject) (ChangeDriverPINResponseObject, error)
	// ConfirmDriverPINReset Set a new PIN with the code, and sign in
	// (POST /driver/pin-reset/confirm)
	ConfirmDriverPINReset(ctx context.Context, request ConfirmDriverPINResetRequestObject) (ConfirmDriverPINResetResponseObject, error)
	// RequestDriverPINReset Ask for a code to set a new PIN
	// (POST /driver/pin-reset/request)
	RequestDriverPINReset(ctx context.Context, request RequestDriverPINResetRequestObject) (RequestDriverPINResetResponseObject, error)
	// DriverSync Send what the phone did, and get what changed
	// (POST /driver/sync)
	DriverSync(ctx context.Context, request DriverSyncRequestObject) (DriverSyncResponseObject, error)
	// ListDrivers List the company's drivers
	// (GET /drivers)
	ListDrivers(ctx context.Context, request ListDriversRequestObject) (ListDriversResponseObject, error)
	// GetPublicSpecification The public operations' specification
	// (GET /openapi.json)
	GetPublicSpecification(ctx context.Context, request GetPublicSpecificationRequestObject) (GetPublicSpecificationResponseObject, error)
	// ListShipments List shipments, newest first unless sorted otherwise
	// (GET /shipments)
	ListShipments(ctx context.Context, request ListShipmentsRequestObject) (ListShipmentsResponseObject, error)
	// CreateShipment Book a shipment
	// (POST /shipments)
	CreateShipment(ctx context.Context, request CreateShipmentRequestObject) (CreateShipmentResponseObject, error)
	// GetShipment One shipment
	// (GET /shipments/{ref})
	GetShipment(ctx context.Context, request GetShipmentRequestObject) (GetShipmentResponseObject, error)
	// UpdateShipment Change a booking
	// (PATCH /shipments/{ref})
	UpdateShipment(ctx context.Context, request UpdateShipmentRequestObject) (UpdateShipmentResponseObject, error)
	// AssignShipment Assign a driver, change the driver, or take the driver off
	// (POST /shipments/{ref}/assign)
	AssignShipment(ctx context.Context, request AssignShipmentRequestObject) (AssignShipmentResponseObject, error)
	// CancelShipment Cancel a shipment
	// (POST /shipments/{ref}/cancel)
	CancelShipment(ctx context.Context, request CancelShipmentRequestObject) (CancelShipmentResponseObject, error)
	// ShipmentEvents A shipment's history, oldest first, and where its truck was last seen
	// (GET /shipments/{ref}/events)
	ShipmentEvents(ctx context.Context, request ShipmentEventsRequestObject) (ShipmentEventsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

